func testNotaFiscalItemGradeToOneSetOpProdutoTamanhoUsingPtam(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a NotaFiscalItemGrade
	var b, c ProdutoTamanho

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, notaFiscalItemGradeDBTypes, false, strmangle.SetComplement(notaFiscalItemGradePrimaryKeyColumns, notaFiscalItemGradeColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, produtoTamanhoDBTypes, false, strmangle.SetComplement(produtoTamanhoPrimaryKeyColumns, produtoTamanhoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, produtoTamanhoDBTypes, false, strmangle.SetComplement(produtoTamanhoPrimaryKeyColumns, produtoTamanhoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*ProdutoTamanho{&b, &c} {
		err = a.SetPtam(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Ptam != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.PtamNotaFiscalItemGrades[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.PtamID != x.PtamID {
			t.Error("foreign key was wrong value", a.PtamID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.PtamID))
		reflect.Indirect(reflect.ValueOf(&a.PtamID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if a.PtamID != x.PtamID {
			t.Error("foreign key was wrong value", a.PtamID, x.PtamID)
		}
	}
}

